  0 <= b -> b + c < 2 ^ 47 -> 0 <= u <= c -> 0 <= u' <= c -> u <> u' -> b mod 8 = 0 -> c mod 8 <> 0 ->
  cellA M 0x1391b8 8 0x1419f8 -> cellA M 0x1419f8 8 SB -> cellA M (SB + (b + c) / 8) 1 v -> (v = 252 \/ 1 <= v <= c mod 8) ->
  exists regs', msteps ASEGS (mkst regs (0x7c518 : word) M rom) (mkst regs' (0x7c524 : word) M rom)
    /\ (forall r : reg, r <> 10%bv -> r <> 11%bv -> r <> 12%bv -> r <> 21%bv -> getr regs' r = getr regs r).
Proof.
